import { setTimeout as sleep } from 'node:timers/promises';
import { one, openDatabase, type JobRow } from './db.ts';

/** Time per step. */
const STEP_MS = 100;
/** Back-off before a failed attempt is retried (the brief allows 250 ms to 2 s). */
const RETRY_DELAY_MS = 500;
/** Total attempts allowed, including the first. */
const MAX_ATTEMPTS = 3;
/** How long an idle worker waits before looking for queued jobs again (pickup must be within 1 s). */
const POLL_MS = 200;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function isoNow(): string {
  return new Date().toISOString();
}

/** Records that this worker is alive. The server reports "up" while this is at most 3 s old. */
function heartbeat(): void {
  db.prepare(
    "INSERT INTO heartbeat (name, ts) VALUES ('worker', ?) ON CONFLICT (name) DO UPDATE SET ts = excluded.ts",
  ).run(Date.now());
}

/**
 * Jobs left `running` by a worker that died are queued again. The interrupted attempt is handed
 * back (attempts is decremented), so it is re-run under the same attempt number and the retry rules
 * still apply exactly as if it had not been interrupted.
 */
function recoverInterrupted(): number {
  const result = db
    .prepare("UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'")
    .run(isoNow());
  return Number(result.changes);
}

/** Atomically takes the oldest eligible queued job and marks it running for a new attempt. */
function claimNext(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = one<JobRow>(
      db,
      "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1",
      Date.now(),
    );
    if (!row) {
      db.exec('COMMIT');
      return undefined;
    }
    db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ?").run(isoNow(), row.seq);
    db.exec('COMMIT');
    return { ...row, status: 'running', attempts: row.attempts + 1, completed: 0 };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

function setProgress(job: JobRow, completed: number): void {
  db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?').run(completed, isoNow(), job.seq);
}

function complete(job: JobRow): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, completed = steps, updated_at = ? WHERE seq = ?",
  ).run(job.input.toUpperCase(), isoNow(), job.seq);
}

/** After a failed attempt: queue another attempt after a delay, or give up after the last one. */
function failAttempt(job: JobRow): void {
  if (job.attempts >= MAX_ATTEMPTS) {
    db.prepare(
      "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, completed = 0, updated_at = ? WHERE seq = ?",
    ).run(isoNow(), job.seq);
  } else {
    db.prepare(
      "UPDATE jobs SET status = 'queued', completed = 0, run_after = ?, updated_at = ? WHERE seq = ?",
    ).run(Date.now() + RETRY_DELAY_MS, isoNow(), job.seq);
  }
}

/** Hands an in-progress attempt back to the queue during a graceful shutdown. */
function release(job: JobRow): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), completed = 0, run_after = 0, updated_at = ? WHERE seq = ?",
  ).run(isoNow(), job.seq);
}

/** Runs one attempt of a job. Returns when the attempt has completed, failed, or been released. */
async function processAttempt(job: JobRow): Promise<void> {
  // Attempt n fails at its first step, before any progress, when n <= failAttempts.
  const willFail = job.attempts <= job.fail_attempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return release(job);
    if (step === 1 && willFail) return failAttempt(job);
    setProgress(job, step);
    heartbeat();
  }
  complete(job);
}

async function main(): Promise<void> {
  const recovered = recoverInterrupted();
  if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
  heartbeat();
  console.log('worker started');

  while (!stopping) {
    heartbeat();
    const job = claimNext();
    if (!job) {
      await sleep(POLL_MS);
      continue;
    }
    await processAttempt(job);
  }

  db.close();
  console.log('worker stopped');
  process.exit(0);
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});

