import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { jobToJson, many, one, openDatabase, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_FRESH_MS = 3_000;
/** Bodies larger than this are rejected; the job payload is at most ~1 KB of input. */
const MAX_BODY_BYTES = 64 * 1024;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError {
  field: string;
  message: string;
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

const notFound = (res: ServerResponse) => sendError(res, 404, 'not_found', 'No such resource.');
const methodNotAllowed = (res: ServerResponse) => sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.');

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Reads the whole body as text. Resolves null if it exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return; // keep draining so the response can be written
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

/** Validates a parsed body. Returns the payload with defaults applied, or the offending fields. */
function validatePayload(body: unknown): { payload: Payload } | { fields: FieldError[] } {
  if (!isPlainObject(body)) return { fields: [{ field: 'body', message: 'The body must be a JSON object.' }] };
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const { input, steps = 5, failAttempts = 0 } = body;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input is required and must be a string.' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters.' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace.' });
  }

  const checkInt = (name: string, value: unknown, min: number, max: number) => {
    if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
      fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
    }
  };
  checkInt('steps', steps, 1, 20);
  checkInt('failAttempts', failAttempts, 0, 5);

  if (fields.length > 0) return { fields };
  return { payload: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

function getJobRow(id: string): JobRow | undefined {
  return one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

type CreateResult = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };

/**
 * Creates a job, or resolves an idempotent replay, in one immediate transaction so that two
 * submissions with the same key cannot both insert.
 */
function createJob(payload: Payload, key: string | undefined): CreateResult {
  const canonical = JSON.stringify({ input: payload.input, steps: payload.steps, failAttempts: payload.failAttempts });
  db.exec('BEGIN IMMEDIATE');
  let result: CreateResult;
  try {
    if (key !== undefined) {
      const existing = one<{ payload: string; job_id: string }>(db, 'SELECT payload, job_id FROM idempotency WHERE key = ?', key);
      if (existing) {
        const row = getJobRow(existing.job_id);
        result = existing.payload === canonical && row ? { kind: 'replayed', row } : { kind: 'conflict' };
        db.exec('COMMIT');
        return result;
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, now, now);
    if (key !== undefined) {
      db.prepare('INSERT INTO idempotency (key, payload, job_id) VALUES (?, ?, ?)').run(key, canonical, id);
    }
    db.exec('COMMIT');
    result = { kind: 'created', row: getJobRow(id)! };
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  const rawKey = req.headers['idempotency-key'];
  let key: string | undefined;
  if (rawKey !== undefined) {
    if (typeof rawKey === 'string' && IDEMPOTENCY_KEY.test(rawKey)) key = rawKey;
    else fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const text = await readBody(req);
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (text === null) {
    fields.push({ field: 'body', message: `The body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    let parsed: unknown;
    let parsedOk = true;
    try {
      parsed = JSON.parse(text);
    } catch {
      parsedOk = false;
    }
    if (!parsedOk) fields.push({ field: 'body', message: 'The body is not valid JSON.' });
    else {
      const v = validatePayload(parsed);
      if ('fields' in v) fields.push(...v.fields);
      else {
        if (fields.length > 0) return sendError(res, 400, 'invalid_request', 'Invalid request.', fields);
        const result = createJob(v.payload, key);
        if (result.kind === 'conflict') {
          return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        }
        return send(res, result.kind === 'created' ? 201 : 200, jobToJson(result.row));
      }
    }
  }

  sendError(res, 400, 'invalid_request', 'Invalid request.', fields);
}

function handleHealth(res: ServerResponse): void {
  const hb = one<{ ts: number }>(db, "SELECT ts FROM heartbeat WHERE name = 'worker'");
  const up = hb !== undefined && Date.now() - hb.ts <= WORKER_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
  const method = req.method ?? 'GET';

  if (path === '/health') return method === 'GET' ? handleHealth(res) : methodNotAllowed(res);
  if (path === '/') {
    if (method !== 'GET') return methodNotAllowed(res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (path === '/api/jobs') {
    if (method === 'POST') return handleCreate(req, res);
    if (method !== 'GET') return methodNotAllowed(res);
    const rows = many<JobRow>(db, 'SELECT * FROM jobs ORDER BY seq DESC');
    return send(res, 200, { jobs: rows.map(jobToJson) });
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return notFound(res);
    }
    const row = getJobRow(id);
    return row ? send(res, 200, jobToJson(row)) : notFound(res);
  }
  notFound(res);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
